<?php
declare(strict_types=1);
function toolsHeaders(): void { header("Content-Security-Policy: default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin'); }
function toolsStart(string $title,string $description,string $canonical,string $name=''):void { toolsHeaders();$schema=['@context'=>'https://schema.org','@type'=>'WebApplication','name'=>$name?:$title,'description'=>$description,'applicationCategory'=>'BusinessApplication','offers'=>['@type'=>'Offer','price'=>'0','priceCurrency'=>'CAD']];?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?></title><meta name="description" content="<?=h($description)?>"><link rel="canonical" href="<?=h($canonical)?>"><link rel="stylesheet" href="/tools/_assets/tools.css"><script type="application/ld+json"><?=json_encode($schema,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script></head><body><header class="site-head"><a href="/tools/" aria-label="Ittai tools home"><picture><source media="(prefers-color-scheme:dark)" srcset="/tools/_assets/wordmark-dark.svg"><img src="/tools/_assets/wordmark-navy-gold.svg" alt="Ittai"></picture></a></header><main class="wrap"><?php }
function toolsEnd():void {?></main><footer><div class="wrap"><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a></div></footer></body></html><?php }
function moneyField(string $name,string $label,string $value='',string $note='',bool $required=false):void {?><div class="field"><label for="<?=h($name)?>"><?=h($label)?></label><div class="input-prefix"><span>$</span><input id="<?=h($name)?>" name="<?=h($name)?>" type="number" min="0" step="0.01" value="<?=h($value)?>" <?=$required?'required':''?> inputmode="decimal"></div><?php if($note):?><small><?=h($note)?></small><?php endif?><p class="error" data-error="<?=h($name)?>"></p></div><?php }
function numberField(string $name,string $label,string $value,string $suffix='',string $note='',string $min='0',string $max='100',string $step='0.01'):void {?><div class="field"><label for="<?=h($name)?>"><?=h($label)?></label><div class="input-suffix"><input id="<?=h($name)?>" name="<?=h($name)?>" type="number" min="<?=h($min)?>" max="<?=h($max)?>" step="<?=h($step)?>" value="<?=h($value)?>" required inputmode="decimal"><?php if($suffix):?><span><?=h($suffix)?></span><?php endif?></div><?php if($note):?><small><?=h($note)?></small><?php endif?><p class="error" data-error="<?=h($name)?>"></p></div><?php }
function nextStep(bool $email):void {?><section class="next"><h2>Next step</h2><p>Ittai works this out from your real time clock and receipts. <a href="/">See what Ittai does</a></p><?php if($email):?><form class="email-form" data-email-form><input type="hidden" name="tool"><input type="hidden" name="inputs"><input type="hidden" name="t"><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required></div><div class="hp" aria-hidden="true"><label>Leave this empty <input name="hp" tabindex="-1" autocomplete="off"></label></div><label class="check"><input type="checkbox" name="save"> <span><?=h(SavedNumbersService::SAVE_TEXT)?></span></label><label class="check"><input type="checkbox" name="news" disabled> <span><?=h(SavedNumbersService::NEWS_TEXT)?></span></label><label class="check"><input type="checkbox" name="benchmarks" disabled> <span><?=h(SavedNumbersService::BENCHMARK_TEXT)?></span></label><p class="privacy-note">We send this one email. If you tick Save, your numbers are kept until you delete them or don't use them for 12 months.</p><button type="submit">Email me this result</button><p class="form-status" role="status"></p></form><?php endif?></section><?php }
